#include <atomic>

// The originals were adjacent non-zero-width bit-fields, which form ONE
// memory location: two concurrent writes conflict and the program has a
// data race. Separate scalar objects are separate memory locations.
struct Flags {
    std::atomic<bool> bid_changed{false};
    std::atomic<bool> ask_changed{false};
};

void mark_bid(Flags& flags) {
    // Relaxed: nothing else is being published through this flag.
    flags.bid_changed.store(true, std::memory_order_relaxed);
}

void mark_ask(Flags& flags) {
    flags.ask_changed.store(true, std::memory_order_relaxed);
}

#include <atomic>
#include <cstdint>

struct Quote {
    std::int64_t bid_ticks;
    std::int64_t ask_ticks;
};

Quote quote{};
std::atomic<bool> ready{false};

void produce() {
    quote = Quote{101, 102};                             // (1)
    ready.store(true, std::memory_order_release);        // (2)
}

bool consume(Quote& out) {
    if (!ready.load(std::memory_order_acquire)) {        // (3)
        return false;
    }
    out = quote;                                         // (4)
    return true;
}

// The chain: (1) is sequenced-before (2); (2) synchronizes-with (3)
// BECAUSE (3) reads the value (2) wrote; (3) is sequenced-before (4).
// The transitive closure gives (1) happens-before (4), so the two
// conflicting plain accesses to `quote` are ordered and race-free.

#include <atomic>
#include <cstdint>

static_assert(std::atomic<std::uint64_t>::is_always_lock_free,
              "ticket dispenser must not fall back to a library lock");

std::uint64_t next_ticket() {
    static std::atomic<std::uint64_t> ticket{0};
    // fetch_add returns the value from BEFORE the increment, so callers
    // receive 0, 1, 2, ... with no duplicates.
    //
    // Relaxed is sufficient: every increment joins this object's
    // modification order, so none is lost. It publishes nothing about
    // any other location - that needs a separate release/acquire pair.
    return ticket.fetch_add(1, std::memory_order_relaxed);
}

#include <atomic>

bool record_high(std::atomic<long>& peak, long candidate) {
    // One load; the failed CAS refreshes `observed` for us.
    long observed = peak.load(std::memory_order_relaxed);

    while (candidate > observed) {
        // weak: this loop already retries, so a spurious failure costs
        // one more iteration and avoids the nested retry a strong CAS
        // may have to perform on an LL/SC machine.
        //
        // success: relaxed - we publish no other state through `peak`.
        // failure: relaxed - the observed value is only compared, never
        // used to reach other memory. (Release/acq_rel are ill-formed
        // for the failure path: a failed CAS performs no write.)
        if (peak.compare_exchange_weak(observed, candidate,
                                       std::memory_order_relaxed,
                                       std::memory_order_relaxed)) {
            return true;
        }
    }
    return false;
}

#include <atomic>
#include <cstdint>

std::atomic<std::uint64_t> hits{0};
std::atomic<bool> ready{false};
std::atomic<int> owner{0};
std::atomic<bool> flag_a{false};
int payload = 0;

void ladder() {
    // relaxed: only this object's value and modification order matter.
    // No other location is being ordered.
    hits.fetch_add(1, std::memory_order_relaxed);

    // release: publishes everything sequenced before it (the write to
    // `payload`) to whichever thread's acquire reads THIS value.
    payload = 42;
    ready.store(true, std::memory_order_release);

    // acquire: if this reads the release above, that release
    // synchronizes with it and `payload` may be read race-free.
    if (ready.load(std::memory_order_acquire)) {
        payload += 1;
    }

    // acq_rel: one RMW that consumes state published by the previous
    // owner (acquire half) and publishes this owner's state onward to
    // the next (release half).
    owner.exchange(1, std::memory_order_acq_rel);

    // seq_cst: needed when operations on INDEPENDENT atomics must share
    // one globally agreed order - Dekker-style mutual flags, a global
    // phase decision, or readers that must agree on the order of two
    // unrelated writes (IRIW). Acquire/release cannot supply that.
    flag_a.store(true, std::memory_order_seq_cst);
}

#include <atomic>
#include <cstddef>

struct Resource {
    int handle;
};

struct Control {
    std::atomic<std::size_t> references{1};
    Resource resource;
};

void add_reference(Control* control) {
    control->references.fetch_add(1, std::memory_order_relaxed);
}

void release(Control* control) {
    // Release on every decrement: each owner publishes its prior use of
    // `resource` before dropping its reference.
    if (control->references.fetch_sub(1, std::memory_order_release) == 1) {
        // fetch_sub returns the count from BEFORE the decrement, so 1
        // means this call dropped the last reference.
        //
        // Sound because the decrements are read-modify-writes: they form
        // a release sequence in `references`'s modification order, and
        // this final RMW read from it. The acquire fence therefore picks
        // up every earlier owner's released effects before destruction.
        //
        // A relaxed final decrement would acquire nothing, and the
        // destructor could run before earlier owners' writes are visible.
        std::atomic_thread_fence(std::memory_order_acquire);
        delete control;
    }
}

#include <array>
#include <atomic>
#include <cstddef>
#include <optional>

std::array<std::atomic<int>, 4> slots{};
std::atomic<bool> batch_ready{false};

void publish_batch(const std::array<int, 4>& values) {
    for (std::size_t i = 0; i < values.size(); ++i) {
        slots[i].store(values[i], std::memory_order_relaxed);
    }
    std::atomic_thread_fence(std::memory_order_release);
    // `batch_ready` is the CARRIER: the fences connect only when the
    // consumer's load actually reads this store (or a later member of
    // its release sequence).
    batch_ready.store(true, std::memory_order_relaxed);
}

std::optional<std::array<int, 4>> consume_batch() {
    if (!batch_ready.load(std::memory_order_relaxed)) {
        return std::nullopt;  // read no carrier value: no edge at all
    }
    std::atomic_thread_fence(std::memory_order_acquire);

    // Hoisting any of these loads above the fence destroys the pattern:
    // the acquire fence orders operations that come AFTER it, so a slot
    // load moved above it could observe a pre-publication value.
    std::array<int, 4> values{};
    for (std::size_t i = 0; i < values.size(); ++i) {
        values[i] = slots[i].load(std::memory_order_relaxed);
    }
    return values;
}

#include <atomic>
#include <mutex>

struct Config {
    int max_order_size;
};

std::atomic<Config*> current_config{nullptr};
std::mutex config_mutex;

Config& get_config() {
    // (1) Acquire, not relaxed: a non-null pointer must arrive together
    // with the visibility of the pointee's initialisation.
    Config* config = current_config.load(std::memory_order_acquire);
    if (config != nullptr) {
        return *config;
    }

    std::lock_guard lock{config_mutex};

    // (2) Re-check: another thread may have published while this one
    // waited for the mutex.
    config = current_config.load(std::memory_order_acquire);
    if (config == nullptr) {
        // (3) Construction completes here, entirely sequenced before...
        config = new Config{10'000};
        // (4) ...the release store, which publishes it. Any later write
        // through `config` would NOT be covered and would race with
        // fast-path readers.
        current_config.store(config, std::memory_order_release);
    }
    return *config;
}

