#include <atomic>

// volatile supplies NONE of the three things this loop needed:
//   - no atomicity of the access,
//   - no happens-before edge with the other thread,
//   - no exemption from the data-race rule (the original is still UB).
// It only makes each access an observable side effect the compiler may
// not elide or merge - which is why it exists for memory-mapped I/O.
std::atomic<bool> stop{false};

void request_stop() {
    stop.store(true, std::memory_order_release);
}

void poll() {
    while (!stop.load(std::memory_order_acquire)) {
    }
}

#include <atomic>

std::atomic<int> sb_x{0};
std::atomic<int> sb_y{0};
int sb_r1 = -1;
int sb_r2 = -1;

void sb_first(std::memory_order store_order,
              std::memory_order load_order) {
    sb_x.store(1, store_order);
    sb_r1 = sb_y.load(load_order);
}

void sb_second(std::memory_order store_order,
               std::memory_order load_order) {
    sb_y.store(1, store_order);
    sb_r2 = sb_x.load(load_order);
}

// Question: (sb_r1, sb_r2) == (0, 0)?
//
// relaxed          ALLOWED    No cross-object ordering at all; each
//                             object has only its own modification
//                             order.
// release/acquire  ALLOWED    Each load reads the INITIAL value, so it
//                             reads from no release: no
//                             synchronizes-with edge is created and
//                             nothing forbids the outcome.
// seq_cst          FORBIDDEN  All four operations join one total order
//                             S. Both loads reading 0 forces each load
//                             before the other thread's store, while
//                             each store precedes its own thread's
//                             load - a four-edge cycle no total order
//                             can contain.
